/* Python-motor: Pyodide + SymPy, kører helt lokalt i browseren */
const BASE = self.location.href.replace(/[^/]*$/, '');
const PY_SRC = "\"\"\"CAS-motor der kører i Pyodide (web worker). Udfører opgavens trin i rækkefølge\ni et frisk navnerum, så definitioner kun gælder nedad og kun i opgaven.\"\"\"\nimport json, io, contextlib, math, traceback, re\nimport sympy\nfrom sympy.printing.latex import LatexPrinter\nfrom sympy import latex, Basic, sympify, S\n\nPRELUDE = '''\nfrom sympy import *\nfrom statistics import linear_regression, correlation, mean, stdev, NormalDist\nimport math\nimport mpmath\n\ndef _rødder(f, udtryk, x, a, b, n):\n    # fortegnsskift på [a; b], forfinet med halvering\n    rødder, forrige = [], None\n    for i in range(n + 1):\n        t = a + (b - a) * i / n\n        try:\n            v = complex(f(t))\n            v = v.real if abs(v.imag) < 1e-12 and math.isfinite(v.real) else None\n        except Exception:\n            v = None\n        if v is None:\n            forrige = None\n            continue\n        if v == 0:\n            # et nulpunkt, men ikke hvor funktionen er 0 i et helt stykke (fx e^(−0,0065t²) = 0 langt ude, fordi tallet bliver for lille)\n            try:\n                nabo = float(f(t + (b - a) / n / 2))\n            except Exception:\n                nabo = 1.0\n            if nabo != 0:\n                rødder.append(t)\n        elif forrige is not None and forrige[1] * v < 0:\n            lo, hi, flo = forrige[0], t, forrige[1]\n            for _ in range(80):\n                m = (lo + hi) / 2\n                try:\n                    fm = float(f(m))\n                except Exception:\n                    break\n                if fm == 0 or (hi - lo) < 1e-13 * max(1, abs(m)):\n                    lo = hi = m\n                    break\n                if (fm < 0) == (flo < 0):\n                    lo, flo = m, fm\n                else:\n                    hi = m\n            r = (lo + hi) / 2\n            # et fortegnsskift ved en lodret asymptote er ikke en rod\n            try:\n                if abs(float(f(r))) < 1e-6 * max(1, abs(forrige[1]), abs(v)):\n                    rødder.append(r)\n            except Exception:\n                pass\n        forrige = (t, v)\n    return rødder\n\n\ndef _svært_integral(f, x):\n    # rødder af andet end et førstegradspolynomium (fx √(1 + f′(x)²) i en kurvelængde): integrate kan her\n    # regne i timevis eller give et forkert fortegn, så integralet regnes numerisk\n    for p in f.atoms(Pow):\n        if p.has(x) and not p.exp.is_Integer:\n            try:\n                if Poly(p.base, x).degree() > 1:\n                    return True\n            except Exception:\n                return True\n    return False\n\n\ndef _nint(f, x, a, b):\n    # numerisk integral (mpmath, delt op i stykker, så knæk fra |…| og gaffelfunktioner ikke snyder); None hvis det ikke er et reelt tal\n    try:\n        g = lambdify(x, f, 'mpmath')\n        a, b = float(a), float(b)\n        v = mpmath.quad(g, mpmath.linspace(a, b, 17))\n        if isinstance(v, mpmath.mpc):\n            if abs(v.imag) > 1e-9 * max(1, abs(v.real)):\n                return None\n            v = v.real\n        return float(v)\n    except Exception:\n        return None\n\n\ndef bestemt_integral(f, grænser):\n    # det bestemte integral ∫ₐᵇ f dx: eksakt, når integrate kan og svaret passer med en numerisk kontrol, ellers numerisk\n    x, a, b = grænser\n    f, a, b = sympify(f), sympify(a), sympify(b)\n    if not (f.free_symbols - {x}) and a.is_number and b.is_number and a.is_finite and b.is_finite:\n        v = _nint(f, x, a, b)\n        if v is not None:\n            if not _svært_integral(f, x):\n                try:\n                    eksakt = integrate(f, (x, a, b))\n                    if not eksakt.has(Integral) and abs(complex(eksakt.evalf()) - v) <= 1e-6 * max(1, abs(v)):\n                        return eksakt\n                except Exception:\n                    pass\n            return Float(v, 15)\n    if _svært_integral(f, x):\n        return Integral(f, (x, a, b))\n    return integrate(f, (x, a, b))\n\n\ndef nløs(ligning, x, a=None, b=None, n=4000):\n    # numerisk løsning: find fortegnsskift og forfin (bruges, når ligningen ikke kan løses eksakt)\n    udtryk = ligning.lhs - ligning.rhs if isinstance(ligning, Equality) else ligning\n    if udtryk.has(Integral):\n        # et integral med den ukendte i en grænse regnes numerisk for hver værdi: færre punkter\n        f = lambdify(x, udtryk, 'mpmath')\n        n = min(n, 200)\n    else:\n        f = lambdify(x, udtryk, 'math')\n    if a is not None and b is not None:\n        rødder = _rødder(f, udtryk, x, float(a), float(b), n)\n    else:\n        rødder = _rødder(f, udtryk, x, -50.0, 50.0, n)\n        # et integral er dyrt at regne ud: søg kun længere ude, hvis der ikke er nogen løsning tæt på 0\n        if not (rødder and udtryk.has(Integral)):\n            rødder += _rødder(f, udtryk, x, 50.0, 1000.0, n) + _rødder(f, udtryk, x, -1000.0, -50.0, n)\n    unikke = []\n    for r in sorted(rødder):\n        if not unikke or abs(r - unikke[-1]) > 1e-7 * max(1, abs(r)):\n            unikke.append(r)\n    return [Float(r, 15) for r in unikke]\n\n\ndef nløs_betinget(ligning, x, betingelse):\n    # numerisk løsning, der opfylder betingelsen (fx t > 1,42 eller 0 ≤ t ≤ 36)\n    mængde = betingelse.as_set() if hasattr(betingelse, 'as_set') else S.Reals\n    lo, hi = mængde.inf, mængde.sup\n    if lo.is_finite and hi.is_finite:\n        kandidater = nløs(ligning, x, lo, hi, 8000)\n    elif lo.is_finite:\n        kandidater = nløs(ligning, x, lo, lo + 50, 4000) + nløs(ligning, x, lo + 50, lo + 1000, 4000)\n    elif hi.is_finite:\n        kandidater = nløs(ligning, x, hi - 50, hi, 4000) + nløs(ligning, x, hi - 1000, hi - 50, 4000)\n    else:\n        kandidater = nløs(ligning, x)\n    return [r for r in kandidater if mængde.contains(r) == True]\n\n\nclass Elevfejl(Exception):\n    # en fejl med en besked til eleven, som vises, som den er\n    pass\n\n\nclass Vektor(ImmutableDenseMatrix):\n    # en søjlevektor: + og − som vektorer, tal·vektor, og vektor·vektor er prikproduktet\n    def __new__(cls, *k):\n        if len(k) == 1 and hasattr(k[0], 'shape'):\n            # en ny matrix af klassen (Punkt eller Vektor), ikke den samme genbrugt\n            return super().__new__(cls, k[0].tolist())\n        if len(k) == 3 and all(isinstance(a, int) or getattr(a, 'is_Integer', False) for a in k[:2]) and isinstance(k[2], (list, tuple, Tuple)):\n            # SymPy selv (fx .subs efter diff) bygger en ny matrix som (rækker, søjler, indgange)\n            return super().__new__(cls, int(k[0]), int(k[1]), list(k[2]))\n        return super().__new__(cls, [[sympify(x)] for x in k])\n    def __mul__(self, o):\n        if isinstance(o, MatrixBase) and o.shape == self.shape:\n            return (self.T * o)[0]\n        return Vektor(super().__mul__(o))\n    def __rmul__(self, o):\n        if isinstance(o, MatrixBase) and o.shape == self.shape:\n            return (o.T * self)[0]\n        return Vektor(super().__rmul__(o))\n    def __add__(self, o):\n        return Vektor(super().__add__(o))\n    def __radd__(self, o):\n        return Vektor(super().__radd__(o))\n    def __sub__(self, o):\n        return Vektor(super().__sub__(o))\n    def __rsub__(self, o):\n        return Vektor(super().__rsub__(o))\n    def __neg__(self):\n        return Vektor(super().__neg__())\n    def __truediv__(self, o):\n        return Vektor(super().__truediv__(o))\n    def _latex(self, printer):\n        BS = chr(92)\n        return BS + 'begin{pmatrix}' + (BS + BS).join(printer._print(x) for x in self) + BS + 'end{pmatrix}'\n\n\ndef indsæt(u, værdier):\n    # sæt værdier ind for konstanter, der fik en værdi, efter u blev defineret (k i F(x) = x²/2 + k)\n    # symbolerne findes på navnet, så også a = symbols('a', positive=True) (grundtallet i b·aᵗ) bliver erstattet\n    fri = u.free_symbols if hasattr(u, 'free_symbols') else set()\n    d = {s: værdier[s.name] for s in fri if s.name in værdier}\n    d.update({Symbol(n, real=True): v for n, v in værdier.items()})\n    ny = u.subs(d) if hasattr(u, 'subs') else u\n    return type(u)(ny) if isinstance(u, Vektor) else ny\n\n\n_DGL_METODER = ['Bernoulli', '1st_linear', 'separable', '1st_rational_riccati', '1st_homogeneous_coeff_best', 'almost_linear',\n                'nth_linear_constant_coeff_homogeneous', 'nth_linear_constant_coeff_undetermined_coefficients',\n                'nth_linear_constant_coeff_variation_of_parameters']\n\n\ndef _decimaler(e, top=True):\n    # alle tal i udtrykket som decimaltal, også inde i eksponenter (evalf lader e^(−3t/100) stå);\n    # 79719^t/100000^t samles først til (79719/100000)^t = 0,79719^t\n    if top:\n        try:\n            e = powsimp(e, combine='base', force=True)\n        except Exception:\n            pass\n    if e.is_number:\n        return e if e.is_Integer else e.evalf(15)\n    if not e.args:\n        return e\n    return e.func(*[_decimaler(a, False) for a in e.args])\n\n\ndef tfraktil(p, df):\n    # p-fraktilen i t-fordelingen med df frihedsgrader (F(t) = 1 − ½·I_{df/(df + t²)}(df/2; ½) for t ≥ 0)\n    F = lambda t: 1 - 0.5 * mpmath.betainc(df / 2, 0.5, 0, df / (df + t * t), regularized=True) if t >= 0 else 0.5 * mpmath.betainc(df / 2, 0.5, 0, df / (df + t * t), regularized=True)\n    return float(mpmath.findroot(lambda t: F(t) - p, 2.0))\n\n\ndef konfidensinterval_hældning(xs, a, s, niveau=0.95):\n    # konfidensintervallet for hældningen i lineær regression: a ± t·s/√(Σ(x − x̄)²)\n    n = len(xs)\n    mx = sum(xs) / n\n    sxx = sum((x - mx) ** 2 for x in xs)\n    t = tfraktil(1 - (1 - niveau) / 2, n - 2)\n    return [float(a) - t * float(s) / math.sqrt(sxx), float(a) + t * float(s) / math.sqrt(sxx)]\n\n\ndef løs_dgl(ligning, fx, betingelser=()):\n    # Den fuldstændige løsning med dsolve – de hurtige metoder først (dsolves eget valg kan tage minutter,\n    # fx for den logistiske ligning). Betingelserne bestemmer derefter konstanten C₁ og ukendte som k\n    # (M′ = −k·M^(2/3) med M(0) = 1 og M(75) = 0,5)\n    t = fx.args[0]\n    decimal = ligning.has(Float) or any(b.has(Float) for b in betingelser)\n    # (med en bestemt metode afprøver dsolve kun den; classify_ode med alle metoder kan hænge i minutter)\n    # Med decimaltal prøves først ligningen, som den er (hurtigst, fx 0,3991·0,79719ᵗ·N), så med brøker\n    løs = None\n    forsøg = [(ligning, list(betingelser))] if decimal else []\n    forsøg.append((nsimplify(ligning, rational=True), [nsimplify(b, rational=True) for b in betingelser]) if decimal else (ligning, list(betingelser)))\n    for L, B in forsøg:\n        for m in _DGL_METODER:\n            try:\n                løs = dsolve(L, fx, hint=m)\n                break\n            except (ValueError, NotImplementedError, TypeError):\n                continue\n        if løs is not None:\n            break\n    if løs is None:\n        raise NotImplementedError('Differentialligningen kan ikke løses eksakt. Tegn et hældningsfelt med en løsningskurve i Plot')\n    løs = list(løs) if isinstance(løs, (list, tuple)) else [løs]\n    # en konstant som R i C′ = P − R·(C − 400) giver en gaffel for R = 0; en konstant i en model er ikke 0\n    løs = [s.replace(lambda e: isinstance(e, Piecewise) and isinstance(e.args[0].cond, Ne), lambda e: e.args[0].expr) for s in løs]\n    if B:\n        # ln(x − 4) for x < 4 (betingelsen y(2) = 5): ln|x − 4| = ln(4 − x) på den side\n        t0 = B[0].lhs.args[0]\n        def vend(e):\n            try:\n                v = e.args[0].subs(t, t0)\n                return log(-e.args[0]) if v.is_number and v.is_negative else e\n            except Exception:\n                return e\n        løs = [s.replace(lambda e: isinstance(e, log) and e.args[0].has(t), vend) for s in løs]\n        C = sorted({u for s in løs for u in s.free_symbols if u.name[:1] == 'C' and u.name[1:].isdigit()}, key=str)\n        konst = sorted(L.free_symbols - {t}, key=str)\n        ud = []\n        for s in løs:\n            # (en implicit løsning, hvor venstresiden ikke er y(t): betingelsen sættes ind på begge sider)\n            lig = [Eq(s.rhs.subs(t, b.lhs.args[0]), b.rhs) if s.lhs == fx else Eq(s.lhs.subs(fx, b.rhs).subs(t, b.lhs.args[0]), s.rhs.subs(t, b.lhs.args[0])) for b in B]\n            brugtC = [u for u in C if any(l.has(u) for l in lig)]\n            # først konstanten C₁ fra den første betingelse, så ukendte som k fra resten (kun reelle løsninger)\n            for kc in (solve(lig[:len(brugtC)], brugtC, dict=True) if brugtC else [{}]):\n                rest = [l.subs(kc) for l in lig[len(brugtC):]]\n                rest = [l for l in rest if l is not S.true]\n                if any(l is S.false for l in rest):\n                    continue\n                brugtK = [u for u in konst if any(l.has(u) for l in rest)]\n                if not rest:\n                    kks = [{}]\n                elif len(rest) == 1 and len(brugtK) == 1:\n                    mængde = solveset(rest[0], brugtK[0], domain=S.Reals)\n                    kks = [{brugtK[0]: v} for v in mængde] if isinstance(mængde, FiniteSet) else []\n                else:\n                    kks = solve(rest, brugtK, dict=True)\n                for kk in kks:\n                    alle = dict(kc); alle.update(kk)\n                    alle = {u: v.subs(kk) for u, v in alle.items()}\n                    try:\n                        if any(abs(complex(N(v)).imag) > 1e-9 * max(1, abs(complex(N(v)))) for v in alle.values() if not v.free_symbols):\n                            continue\n                    except Exception:\n                        pass\n                    ud.append(s.subs(alle))\n        løs = ud\n    # kun løsninger, der er reelle og faktisk passer i ligningen (fx ikke den gren, hvor √y skulle være negativ)\n    løs = [s for s in løs if not (s.rhs.is_number and s.rhs.is_real is False)]\n    if B:\n        t0 = B[0].lhs.args[0]\n        løs = [s for s in løs if s.lhs != fx or _passer(L, fx, s.rhs, t, t0)]\n    løs = [Eq(s.lhs, _pæn(s.rhs, t)) if s.lhs == fx else s for s in løs]\n    if decimal:\n        løs = [Eq(s.lhs, _decimaler(s.rhs)) for s in løs]\n    return løs\n\n\ndef _pæn(u, t):\n    # den korteste form: som den er, ganget ud eller (for et polynomium) faktoriseret\n    # (en lineær ligning giver fx (162·e^(0,0594t) − 162)·e^(−0,069t), som ganget ud er 162·e^(−0,0096t) − 162·e^(−0,069t);\n    # factor kan hænge på udtryk med eksponentialfunktioner, så den bruges kun på polynomier)\n    def tal(e):\n        # talleddene for sig: −√2/(√2 − 2) − 2/(√2 − 2) er 3 + 2√2\n        if e.is_number:\n            try:\n                return radsimp(simplify(e))\n            except Exception:\n                return e\n        return e.func(*[tal(a) for a in e.args]) if e.args else e\n    try:\n        u = tal(u)\n    except Exception:\n        pass\n    kand = [u]\n    try:\n        kand.append(powsimp(expand(u)))\n        if u.is_polynomial(t):\n            kand.append(factor(u))\n        # en logistisk løsning 209·e^(rt)/(e^(rt) + B) skrives 209/(1 + B·e^(−rt))\n        n, d = fraction(u)\n        for e in d.atoms(exp):\n            kand.append(powsimp(expand(n / e)) / powsimp(expand(d / e)))\n        # … og 1/(0,004785 + B·e^(−rt)) skrives 209/(1 + B′·e^(−rt)): konstanten i nævneren bliver 1\n        for v in list(kand):\n            n2, d2 = fraction(v)\n            c0 = expand(d2).as_independent(t)[0] if d2.is_Add or expand(d2).is_Add else 0\n            if c0 != 0 and c0 != 1 and c0.is_number:\n                kand.append(normeret := (n2 / c0) / expand(d2 / c0))\n    except Exception:\n        pass\n    # (en brøk med 1 som konstantled i nævneren foretrækkes, når den ikke er længere)\n    def en(v):\n        _, d2 = fraction(v)\n        if not expand(d2).is_Add:\n            return 1\n        c0 = expand(d2).as_independent(t)[0]\n        # (med decimaltal er konstantleddet 1.0, som ikke er lig med 1 i SymPy)\n        return 0 if c0.is_number and abs(float(c0) - 1) < 1e-12 else 1\n    return min(kand, key=lambda v: (count_ops(v), en(v), len(str(v))))\n\n\ndef _passer(L, fx, y, t, t0):\n    # passer y i differentialligningen L? Regnes med tal i nogle punkter tæt på betingelsens t0\n    try:\n        rest = (L.lhs - L.rhs).subs(fx.diff(t), y.diff(t)).subs(fx, y)\n    except Exception:\n        return True\n    if rest.free_symbols - {t}:\n        return True\n\n    for d in (0.37, 0.11, -0.23, 1.3):\n        try:\n            v = complex(rest.subs(t, t0 + d).evalf(20))\n            s = abs(complex(y.subs(t, t0 + d).evalf(20)))\n        except Exception:\n            continue\n        if not (math.isfinite(v.real) and math.isfinite(v.imag)):\n            continue\n        pass\n        if abs(v) > 1e-8 * max(1, s):\n            return False\n    return True\n\n\ndef komponenter(a, b):\n    # en vektorligning a⃗ = b⃗ er en ligning for hver koordinat\n    return [Eq(x, y) for x, y in zip(a, b)]\n\n\ndef det(a, b):\n    # determinanten af to vektorer i planen: a₁·b₂ − a₂·b₁\n    return a[0] * b[1] - a[1] * b[0]\n\n\ndef tvær(a):\n    # tværvektoren â: vektoren drejet 90° mod uret\n    return Vektor(-a[1], a[0])\n\n\ndef reelle(løsninger, ligning=None, x=None):\n    # kun reelle løsninger, der faktisk passer i ligningen (fx ikke v = −7,88 i v**0.16, som ikke er et reelt tal)\n    if not isinstance(løsninger, (list, tuple)):\n        return løsninger\n    udtryk = (ligning.lhs - ligning.rhs) if isinstance(ligning, Equality) else ligning\n    if not isinstance(udtryk, Expr):\n        udtryk = None\n    ud = []\n    for s in løsninger:\n        try:\n            v = complex(N(s, 20))\n        except (TypeError, ValueError):\n            ud.append(s)  # en løsning med ukendte parametre beholdes\n            continue\n        if abs(v.imag) > 1e-9 * max(1, abs(v.real)):\n            continue\n        if udtryk is not None and x is not None:\n            # ikke en løsning, hvor ligningen ikke er defineret (fx R = 0 i (1 − e^(−1,5R))/R, der kom fra at gange med R)\n            try:\n                if any(N(t.subs(x, v.real), 20).has(zoo, nan, oo, -oo) for t in Add.make_args(udtryk)):\n                    continue\n            except Exception:\n                pass\n            try:\n                led = [complex(N(t.subs(x, v.real), 20)) for t in Add.make_args(udtryk)]\n                r = sum(led)\n                skala = 1 + sum(abs(t) for t in led)\n                if abs(r.imag) > 1e-7 * skala or abs(r.real) > 1e-6 * skala:\n                    continue\n            except (TypeError, ValueError, ZeroDivisionError):\n                pass\n        ud.append(Float(v.real, 15) if s.has(I) else s)\n    return ud\n\n\nclass Punkt(Vektor):\n    # et punkt A = (3, 4): regnes som sin stedvektor, men er et punkt.\n    # B − A er vektoren fra A til B; et punkt plus en vektor er et punkt; (A + B)/2 er midtpunktet\n    def __add__(self, o):\n        return Punkt(ImmutableDenseMatrix.__add__(self, o)) if isinstance(o, MatrixBase) else NotImplemented\n    def __radd__(self, o):\n        return Punkt(ImmutableDenseMatrix.__radd__(self, o)) if isinstance(o, MatrixBase) else NotImplemented\n    def __sub__(self, o):\n        if not isinstance(o, MatrixBase):\n            return NotImplemented\n        d = ImmutableDenseMatrix.__sub__(self, o)\n        return Vektor(d) if isinstance(o, Punkt) else Punkt(d)\n    def __rsub__(self, o):\n        return Vektor(ImmutableDenseMatrix.__rsub__(self, o)) if isinstance(o, MatrixBase) else NotImplemented\n    def __mul__(self, o):\n        if isinstance(o, MatrixBase) and o.shape == self.shape:\n            return (self.T * o)[0]\n        return Punkt(ImmutableDenseMatrix.__mul__(self, o))\n    def __rmul__(self, o):\n        if isinstance(o, MatrixBase) and o.shape == self.shape:\n            return (o.T * self)[0]\n        return Punkt(ImmutableDenseMatrix.__rmul__(self, o))\n    def __truediv__(self, o):\n        return Punkt(ImmutableDenseMatrix.__truediv__(self, o))\n    def __neg__(self):\n        return Punkt(ImmutableDenseMatrix.__neg__(self))\n    def _latex(self, printer):\n        BS = chr(92)\n        # koordinaterne skilles med komma – men med semikolon, når der er decimaltal: (1,5; 2)\n        dele = [printer._print(x) for x in self]\n        sep = ';' if any('{,}' in d for d in dele) else ','\n        return BS + 'left(' + (sep + BS + ' ').join(dele) + BS + 'right)'\n\n\n_Abs = Abs\n\n\ndef Abs(x):\n    # |a| er længden af en vektor\n    return sqrt(x * x) if isinstance(x, Vektor) else _Abs(x)\n\n\ndef normcdf(a, b, mu, sigma):\n    # P(a ≤ X ≤ b), når X er normalfordelt med middelværdi μ og spredning σ (a = −∞ giver fordelingsfunktionen F(b))\n    F = lambda v: S.One if v == oo else S.Zero if v == -oo else (1 + erf((v - mu) / (sigma * sqrt(2)))) / 2\n    p = F(b) - F(a)\n    # med tal alene: et decimaltal (et eksakt udtryk med erf siger ikke eleven noget)\n    return p.evalf(15) if not p.free_symbols else p\n\n\ndef normpdf(x, mu, sigma):\n    # tæthedsfunktionen for normalfordelingen N(μ; σ)\n    return exp(-(x - mu) ** 2 / (2 * sigma ** 2)) / (sigma * sqrt(2 * pi))\n\n\ndef invnorm(p, mu=0, sigma=1):\n    # den værdi x, hvor P(X ≤ x) = p (fraktilen)\n    return (mu + sigma * sqrt(2) * erfinv(2 * sympify(p) - 1)).evalf(15)\n\n\ndef _tal(x):\n    # et tal (ikke et symbol, der først bestemmes senere), ellers None\n    try:\n        x = sympify(x)\n        return float(x) if x.is_number and x.is_real else None\n    except Exception:\n        return None\n\n\ndef _da(x):\n    return ('%g' % x).replace('.', ',').replace('-', '−')\n\n\ndef tjek_binomial(n, p):\n    # b(n; p): n er et antal forsøg (helt tal ≥ 1), p en sandsynlighed (0 ≤ p ≤ 1)\n    nf, pf = _tal(n), _tal(p)\n    if nf is not None and (nf < 1 or abs(nf - round(nf)) > 1e-9):\n        raise Elevfejl('Antallet af forsøg n i b(n; p) skal være et helt tal ≥ 1 (her ' + _da(nf) + ')')\n    if pf is not None and not (0 <= pf <= 1):\n        raise Elevfejl('Sandsynligheden p i b(n; p) skal ligge mellem 0 og 1 (her ' + _da(pf) + ')' + ('. Er det en procent, så skriv ' + _da(pf / 100) if 2 <= pf <= 100 else ''))\n\n\ndef tjek_normal(s):\n    sf = _tal(s)\n    if sf is not None and not sf > 0:\n        raise Elevfejl('Spredningen σ i N(μ; σ) skal være positiv (her ' + _da(sf) + ')')\n\n\ndef binompdf(n, p, k):\n    # P(X = k), når X er binomialfordelt med antal n og sandsynlighed p\n    # (k er et antal: et tal, der ikke er helt, har sandsynlighed 0)\n    kf = _tal(k)\n    if kf is not None and abs(kf - round(kf)) > 1e-9:\n        return S.Zero\n    n, k = int(n), int(round(float(k)))\n    if k < 0 or k > n:\n        return S.Zero\n    if n <= 60 and not sympify(p).has(Float):\n        return binomial(n, k) * sympify(p) ** k * (1 - sympify(p)) ** (n - k)\n    pf = float(p)\n    if pf <= 0 or pf >= 1:\n        return Float(1.0 if (pf <= 0 and k == 0) or (pf >= 1 and k == n) else 0.0)\n    return Float(math.exp(math.lgamma(n + 1) - math.lgamma(k + 1) - math.lgamma(n - k + 1) + k * math.log(pf) + (n - k) * math.log(1 - pf)), 15)\n\n\ndef binomcdf(n, p, a, b=None):\n    # P(a ≤ X ≤ b); med tre tal: P(X ≤ a)\n    if b is None:\n        a, b = 0, a\n    a, b = max(int(math.ceil(float(a))), 0), min(int(math.floor(float(b))), int(n))\n    if b < a:\n        return S.Zero\n    led = [binompdf(n, p, k) for k in range(a, b + 1)]\n    if any(isinstance(t, Float) for t in led):\n        return Float(math.fsum(float(t) for t in led), 15)\n    return Add(*led)\n\n\ndef cirkelform(venstre, højre, omskriv=simplify):\n    # x² + y² + ax + by + c = 0 som (x − x₀)² + (y − y₀)² = r² (ellers omskrives begge sider som valgt)\n    x, y = Symbol('x', real=True), Symbol('y', real=True)\n    try:\n        p = Poly(expand(venstre - højre), x, y)\n        A = p.coeff_monomial(x ** 2)\n        if p.total_degree() == 2 and A != 0 and p.coeff_monomial(y ** 2) == A and p.coeff_monomial(x * y) == 0:\n            x0, y0 = -p.coeff_monomial(x) / (2 * A), -p.coeff_monomial(y) / (2 * A)\n            r2 = x0 ** 2 + y0 ** 2 - p.coeff_monomial(1) / A\n            v = Add(Pow(x - x0, 2, evaluate=False), Pow(y - y0, 2, evaluate=False), evaluate=False)\n            return CirkelLigning(v, nsimplify(r2) if r2.has(Float) else r2, x0, y0)\n    except PolynomialError:\n        pass\n    return (omskriv(venstre), omskriv(højre))\n\n\nclass CirkelLigning(tuple):\n    # (venstre side, r², x₀, y₀): vises som ligningen med centrum og radius\n    def __new__(cls, v, r2, x0, y0):\n        return super().__new__(cls, (v, r2, x0, y0))\n\n\ndef plusminus(a, b):\n    # a ± b er intervallet fra a − b til a + b (fx et konfidensinterval)\n    lo, hi = a - b, a + b\n    try:\n        if float(lo) > float(hi):\n            lo, hi = hi, lo\n    except (TypeError, ValueError):\n        pass\n    return Interval(lo, hi)\n\n\ndef heltal_løs(betingelse, fra=0, til=100000):\n    # x er et helt tal (fx antal forsøg n i en binomialfordeling): prøv x = 0, 1, 2, … og behold dem, der passer.\n    # Søgningen stopper, når svaret har været det samme 300 gange i træk efter det sidste skift.\n    ok, sidst_skift, forrige = [], fra, None\n    for i in range(fra, til + 1):\n        try:\n            sand = bool(betingelse(i))\n        except (TypeError, ValueError):\n            sand = False\n        if sand:\n            ok.append(i)\n        if forrige is not None and sand != forrige:\n            sidst_skift = i\n        forrige = sand\n        if ok and i - sidst_skift >= 300:\n            break\n    if not ok:\n        return S.EmptySet\n    # sammenhængende stykker; det sidste fortsætter, hvis det stadig var sandt, da søgningen stoppede\n    stykker, start = [], ok[0]\n    for a, b in zip(ok, ok[1:] + [None]):\n        if b != a + 1:\n            stykker.append((start, a))\n            start = b\n    dele = [Interval(a, oo if (b == ok[-1] and forrige) else b) for a, b in stykker]\n    return Union(*dele) if len(dele) > 1 else dele[0]\n\n\ndef kvartilsæt(data):\n    # mindste, nedre kvartil, median, øvre kvartil og største værdi; kvartilerne er medianen af hver halvdel\n    # (uden medianen selv ved et ulige antal). Outliers ligger mere end 1,5 kvartilbredde uden for kvartilerne.\n    xs = sorted(float(x) for x in data)\n    n = len(xs)\n    def median(l):\n        m = len(l) // 2\n        return l[m] if len(l) % 2 else (l[m - 1] + l[m]) / 2\n    lav, høj = xs[:n // 2], xs[(n + 1) // 2:]\n    q1, q2, q3 = median(lav or xs), median(xs), median(høj or xs)\n    kb = q3 - q1\n    ud = [x for x in xs if x < q1 - 1.5 * kb or x > q3 + 1.5 * kb]\n    inde = [x for x in xs if x not in ud]\n    return {'min': xs[0], 'q1': q1, 'med': q2, 'q3': q3, 'max': xs[-1], 'wlo': inde[0] if inde else xs[0], 'whi': inde[-1] if inde else xs[-1], 'out': ud}\n\n\ndef kvartilsæt_sumkurve(punkter):\n    # kvartilerne aflæst på sumkurven (rette linjestykker mellem punkterne): hvor den kumulerede frekvens er 25, 50 og 75 %\n    def aflæs(p):\n        for (x0, y0), (x1, y1) in zip(punkter, punkter[1:]):\n            if y1 >= p and y1 > y0:\n                return float(x0 + (p - y0) * (x1 - x0) / (y1 - y0)) if p > y0 else float(x0)\n        return float(punkter[-1][0])\n    mindst = float(max(x for x, y in punkter if y <= 1e-9))  # (intervaller uden observationer i starten tæller ikke)\n    størst = float(next(x for x, y in punkter if y >= punkter[-1][1] - 1e-9))\n    return {'min': mindst, 'q1': aflæs(25), 'med': aflæs(50), 'q3': aflæs(75), 'max': størst, 'wlo': mindst, 'whi': størst, 'out': []}\n\n\ndef kvartilsæt_frekvenser(værdier, andele):\n    # kvartilsættet ud fra frekvenserne: p-fraktilen er den mindste observation, hvor den kumulerede frekvens når over p\n    # (når den præcis p, er det gennemsnittet af den og den næste – som medianen ved et lige antal observationer)\n    par = sorted((float(x), float(p)) for x, p in zip(værdier, andele) if p > 0)\n    xs = [x for x, _ in par]\n    def fraktil(p):\n        kum = 0.0\n        for i, (x, q) in enumerate(par):\n            kum += q\n            if abs(kum - p) < 1e-9 and i + 1 < len(par):\n                return (x + par[i + 1][0]) / 2\n            if kum > p:\n                return x\n        return xs[-1]\n    q1, q2, q3 = fraktil(0.25), fraktil(0.5), fraktil(0.75)\n    kb = q3 - q1\n    ud = sorted(set(x for x in xs if x < q1 - 1.5 * kb or x > q3 + 1.5 * kb))\n    inde = [x for x in xs if x not in ud]\n    return {'min': xs[0], 'q1': q1, 'med': q2, 'q3': q3, 'max': xs[-1], 'wlo': inde[0] if inde else xs[0], 'whi': inde[-1] if inde else xs[-1], 'out': ud}\n\n\ndef round(tal, cifre=None):\n    # round() på SymPy-tal giver et almindeligt Python-tal (25.0, ikke 25.0000000000000)\n    import builtins\n    try:\n        if isinstance(tal, Basic) and tal.is_number:\n            tal = float(tal)\n    except Exception:\n        pass\n    return builtins.round(tal, cifre) if cifre is not None else builtins.round(tal)\n\n\ndef som_liste(løsninger):\n    # løsningerne som en liste, sorteret som de vises (mindste først)\n    if not isinstance(løsninger, (list, tuple, FiniteSet)):\n        return []\n    def nøgle(s):\n        try:\n            return float(re(N(s)))\n        except Exception:\n            return 0.0\n    return sorted(list(løsninger), key=nøgle)\n\ndef præcis(u):\n    # decimaltal skrives som brøker (0.5 → 1/2), så svaret bliver præcist\n    try:\n        return u.xreplace({f: nsimplify(f, rational=True) for f in u.atoms(Float)})\n    except AttributeError:\n        return nsimplify(u, rational=True)\n\ndef punkt(fn, t):\n    try:\n        v = complex(fn(t))\n    except Exception:\n        return None\n    if abs(v.imag) > 1e-9 or not math.isfinite(v.real):\n        return None\n    return v.real\n'''\n\n_BASE = {}\nexec(PRELUDE, _BASE)\n\n\n_nul = re.compile(r'(\\d)\\{,\\}(\\d*?)0+(?!\\d)')\n\n\ndef _trim(m):\n    return m.group(1) + ('{,}' + m.group(2) if m.group(2) else '')\n\n\nclass _LG(sympy.Function):\n    # log med grundtal 10 vises som log(x), ikke ln(x)/ln(10)\n    nargs = 1\n    def _latex(self, printer):\n        return r'\\log\\left(%s\\right)' % printer._print(self.args[0])\n\n\ndef _lg(e):\n    if isinstance(e, sympy.Mul):\n        inv = sympy.Pow(sympy.log(10), -1)\n        args = list(e.args)\n        if inv in args:\n            logs = [a for a in args if isinstance(a, sympy.log)]\n            if len(logs) == 1:\n                args.remove(inv); args.remove(logs[0])\n                return sympy.Mul(*args, _LG(logs[0].args[0]), evaluate=False)\n    return e\n\n\ndef _tal(f, cifre):\n    # afrund til et antal betydende cifre og fjern overflødige nuller\n    return sympy.Float(float('%.*g' % (cifre, float(f))), cifre)\n\n\ndef _betydende(t):\n    # antal betydende cifre i et tal skrevet med %g\n    m = t.lstrip('-').split('e')[0]\n    if '.' in m:\n        return len(m.replace('.', '').lstrip('0'))\n    return len(m.lstrip('0').rstrip('0')) or 1\n\n\nKORT = 6   # et decimaltal med højst så mange betydende cifre vises helt (og er eksakt)\n_CIFRE = [None]  # kun visning; nulstilles efter hvert resultat\n\n\ndef _decimal(x, cifre):\n    cifre = _CIFRE[0] or cifre\n    # Decimaltal skrives positionelt (33230,7 – ikke 3,323·10⁴), med tusindtalsmellemrum – undtagen meget store\n    # og meget små (2,166·10¹⁴ i en logistisk løsning, ikke 216 564 622 446 268).\n    # Et kort tal vises helt (81,135); ellers rundes der, og nuller til sidst bliver stående (148,0 og 1,040),\n    # så man kan se, hvor mange cifre der er.\n    if x == 0:\n        return '0'\n    if _CIFRE[0] is not None:\n        # Afrund via scientific notation, også når afrundingen passerer en tierpotens.\n        m, e = ('%.*e' % (cifre - 1, x)).split('e')\n        e = int(e)\n        if not (1e-4 <= abs(x) < 1e10) or e >= cifre:\n            return m.replace('.', '{,}') + r' \\cdot 10^{%d}' % e\n        return ('%.*f' % (max(0, cifre - 1 - e), float(m) * 10**e)).replace('.', '{,}')\n    if not (1e-4 <= abs(x) < 1e10):\n        m, e = ('%.*e' % (max(cifre - 1, 0), x)).split('e')\n        m = m.rstrip('0').rstrip('.').replace('.', '{,}')\n        return m + r' \\cdot 10^{%d}' % int(e)\n    g = '%.12g' % x\n    if 'e' not in g and _betydende(g) <= KORT:\n        t = g\n    else:\n        heltal = len(str(int(abs(x)))) if abs(x) >= 1 else 0\n        if heltal:\n            dec = max(cifre - heltal, 1)\n        else:\n            dec = cifre - 1 - int(math.floor(math.log10(abs(x))))\n        t = '%.*f' % (dec, x)\n        if '.' in t and abs(float(t) - x) <= 1e-12 * abs(x):\n            t = t.rstrip('0').rstrip('.')\n    tegn, t = ('-', t[1:]) if t.startswith('-') else ('', t)\n    hel, _, rest = t.partition('.')\n    if len(hel) > 4:\n        hel = r'\\,'.join([hel[max(i - 3, 0):i] for i in range(len(hel), 0, -3)][::-1])\n    return tegn + hel + ('{,}' + rest if rest else '')\n\n\nclass _Printer(LatexPrinter):\n    def __init__(self, cifre, order=None):\n        super().__init__({'ln_notation': True, 'full_prec': False, 'decimal_separator': 'comma', 'mul_symbol': None, 'order': order})\n        self.cifre = cifre\n\n    def _print_Float(self, f):\n        return _decimal(float(f), self.cifre)\n\n    def _print_Integer(self, n):\n        # store hele tal med tusindtalsmellemrum: 7 000 000\n        v = int(n)\n        if abs(v) < 10000:\n            return str(v)\n        t = str(abs(v))\n        return ('-' if v < 0 else '') + r'\\,'.join([t[max(i - 3, 0):i] for i in range(len(t), 0, -3)][::-1])\n\n\n# Dokumentet regner i grader: cos(13π/45) vises som cos(52°)\n_GRADER = [False]\n\n\ndef _grader(v):\n    def g(t):\n        a = t.args[0]\n        if a.free_symbols or not a.is_number:\n            return t\n        d = sympy.nsimplify(a * 180 / sympy.pi)\n        if not d.is_Rational:\n            return t\n        return t.func(sympy.Symbol(_decimal(float(d), 6) + r'^{\\circ}'), evaluate=False)\n    return v.replace(lambda t: isinstance(t, (sympy.sin, sympy.cos, sympy.tan)), g)\n\n\n_prikfri = re.compile(r'(\\d|\\})\\s+(?=\\{?-?\\d)')\n\n\ndef tex(v, cifre=4, order=None):\n    cifre = _CIFRE[0] or cifre\n    if not isinstance(v, Basic):\n        v = sympify(v)\n    # et interval (fra a ± b) skrives med dansk semikolon: [0,7948; 0,8952]\n    if isinstance(v, sympy.Interval) and v.start.is_finite and v.end.is_finite:\n        return r'\\left[' + tex(v.start, cifre) + r';\\ ' + tex(v.end, cifre) + r'\\right]'\n    if v.has(sympy.Float) and _CIFRE[0] is None:\n        # hele decimaltal (1,0 og 10,0) vises som hele tal, så der ikke står et løst \"1\" foran en parentes\n        try:\n            v = v.xreplace({f: sympy.Integer(int(f)) for f in v.atoms(sympy.Float) if float(f) == int(f) and abs(float(f)) < 1e12})\n        except Exception:\n            pass\n    if v.has(sympy.Float):\n        # fjern regnestøj (fx 7·10⁻¹⁵), og saml et tal med decimaler til ét decimaltal\n        try:\n            støj = {f: sympy.S.Zero for f in v.atoms(sympy.Float) if abs(f) < 1e-11} if _CIFRE[0] is None else {}\n            if støj:\n                v = v.xreplace(støj)\n            if v.is_number and not v.is_Float and not isinstance(v, sympy.Set):\n                v = v.evalf(15 if _CIFRE[0] else 12)\n        except Exception:\n            pass\n    if v.has(sympy.log):\n        try:\n            v = v.replace(lambda e: isinstance(e, sympy.Mul), _lg)\n        except Exception:\n            pass\n    if _GRADER[0] and not isinstance(v, sympy.Set) and v.has(sympy.sin, sympy.cos, sympy.tan):\n        try:\n            v = _grader(v)\n        except Exception:\n            pass\n    s = _Printer(cifre, order).doprint(v)\n    # to tal efter hinanden skal have et gangetegn: 70·0,94^t\n    return _prikfri.sub(lambda m: m.group(1) + r' \\cdot ', s)\n\n\ndef _kort(v):\n    # Decimaltal, der vises helt (højst KORT betydende cifre), er eksakte: 2,5·4 = 10, ikke ≈ 10\n    try:\n        for f in v.atoms(sympy.Float):\n            if _CIFRE[0] and float('%.*g' % (_CIFRE[0], float(f))) != float(f):\n                return False\n            if _betydende('%.12g' % float(f)) > KORT:\n                return False\n        return True\n    except Exception:\n        return False\n\n\ndef grim(v):\n    return v.has(sympy.LambertW) or v.has(sympy.zoo) or v.has(sympy.nan) or v.has(sympy.oo) and not isinstance(v, sympy.Set)\n\n\ndef _ulighed_tex(mængde, x):\n    # intervaller skrevet som uligheder med variablen i midten\n    xs = tex(x)\n    def et(iv):\n        if isinstance(iv, sympy.Interval):\n            a, b = iv.start, iv.end\n            lo = '' if a == -sympy.oo else tex(a) + (r' \\le ' if not iv.left_open else ' < ')\n            hi = '' if b == sympy.oo else (r' \\le ' if not iv.right_open else ' < ') + tex(b)\n            if not lo and not hi:\n                return xs + r' \\in \\mathbb{R}'\n            if not lo:\n                return xs + hi\n            if not hi:\n                return xs + (r' \\ge ' if not iv.left_open else ' > ') + tex(a)\n            return lo + xs + hi\n        if isinstance(iv, sympy.FiniteSet):\n            return r' \\lor '.join(xs + '=' + tex(p) for p in iv)\n        return tex(iv)\n    dele = list(mængde.args) if isinstance(mængde, sympy.Union) else [mængde]\n    return r'\\ \\lor\\ '.join(et(d) for d in dele)\n\n\ndef _generel(mængde, x, deg=False, dec=False):\n    # periodiske løsninger: x = a + p·T, p ∈ ℤ\n    dele = list(mængde.args) if isinstance(mængde, sympy.Union) else [mængde]\n    ud = []\n    for d in dele:\n        if isinstance(d, sympy.ImageSet):\n            lam = d.lamda\n            n = lam.variables[0]\n            e = sympy.expand(lam.expr)\n            T = e.coeff(n)\n            a = sympy.simplify(e - T * n)\n            p = sympy.Symbol('p')\n            o = r'^{\\circ}' if deg else ''\n            # Decimal: startværdien og perioden som decimaltal (x ≈ 0,5236 + p·3,142), ellers eksakt\n            ta = lambda u: tex(u.evalf(15)) if dec and not u.is_Integer else tex(u)\n            led = tex(p) + r'\\cdot ' + ta(T) + o\n            lig = r'\\approx ' if dec and not (a.is_Integer and T.is_Integer) else '='\n            ud.append(tex(x) + lig + (led if a == 0 else ta(a) + o + '+' + led))\n        elif isinstance(d, sympy.FiniteSet):\n            ud += [tex(x) + (r'\\approx ' if dec and not q.is_Integer else '=') + (tex(q.evalf(15)) if dec and not q.is_Integer else tex(q)) + (r'^{\\circ}' if deg else '') for q in d]\n        else:\n            return None\n    return r'\\ \\lor\\ '.join(ud) + r',\\quad p\\in\\mathbb{Z}'\n\n\ndef dansk_fejl(e):\n    t = type(e).__name__\n    m = str(e)\n    if t == 'Elevfejl':\n        return m\n    if t == 'NameError':\n        navn = m.split(\"'\")[1] if \"'\" in m else m\n        # en fordelings parametre (X_n, X_p, X_mu, X_sigma): fordelingen selv mangler, eller dens definition gav en fejl\n        fm = re.match(r'^([A-Z])(?:_?([A-Za-z0-9]*?))?_?(n|p|mu|sigma)$', navn)\n        if fm:\n            return f'{fm.group(1)} er ikke defineret ovenfor (eller definitionen af fordelingen gav en fejl)'\n        return f'{navn} er ikke defineret ovenfor i opgaven'\n    if t == 'TimeoutError':\n        return 'Beregningen tog for lang tid og blev stoppet. Prøv \"Decimal\" eller et enklere udtryk.'\n    if t in ('OverflowError', 'MemoryError') or (t == 'ValueError' and ('limit' in m or 'too large' in m or 'Exceeds' in m)):\n        return 'Tallene bliver for store til at regne med'\n    if t == 'ZeroDivisionError':\n        return 'Udtrykket er ikke defineret (division med 0)'\n    if t == 'NotImplementedError':\n        return 'CAS kan ikke løse dette eksakt. Vælg Decimal for at løse numerisk.'\n    if t == 'TypeError' and 'argument' in m:\n        return 'Forkert antal argumenter til en funktion'\n    if t == 'TypeError' and 'NaN' in m:\n        return 'CAS kunne ikke løse det eksakt. Vælg Decimal for at løse numerisk.'\n    if t in ('ModuleNotFoundError', 'ImportError'):\n        navn = m.split(\"'\")[1] if \"'\" in m else m\n        return f'Modulet {navn} findes ikke her. Grafer tegnes med en Graf-blok (\\\\graf).' if 'matplotlib' in navn else f'Modulet {navn} findes ikke her'\n    if t == 'ShapeError':\n        return 'Vektorerne har ikke lige mange koordinater'\n    if t == 'StatisticsError':\n        return 'Regressionen kan ikke beregnes ud fra disse data'\n    if t == 'SyntaxError':\n        return f'Syntaksfejl i linje {e.lineno}: {e.msg}'\n    return f'{t}: {m}'[:240]\n\n\n_GRIMT = re.compile(r'RootOf|operatorname|LambertW|polylog')\n\n\ndef _kæmpe(latex):\n    # et eksakt resultat, der er for langt eller for teknisk til at læse\n    return len(latex) > 90 or bool(_GRIMT.search(latex))\n\n\ndef _brøk(v):\n    # en brøk, der er svær at læse som tal (1295/36), får også et decimaltal\n    try:\n        return bool(v.is_Rational and not v.is_Integer and (abs(v.q) > 12 or abs(v.p) > 999))\n    except Exception:\n        return False\n\n\n_HØJ_ROD = re.compile(r'\\\\sqrt\\[(?:[4-9]|\\d\\d)\\]')\n\n\ndef _uskøn(latex):\n    # et eksakt tal, der ikke kan bruges i en besvarelse: høje rødder eller meget langt\n    return len(latex) > 48 or bool(_HØJ_ROD.search(latex)) or _kæmpe(latex)\n\n\ndef _py(v):\n    s = str(v)\n    return s if len(s) < 400 else s[:400] + ' …'\n\n\ndef _num(x):\n    try:\n        f = float(x)\n        return f if math.isfinite(f) else None\n    except Exception:\n        return None\n\n\ndef fmt(st, ns):\n    meta = st.get('meta', {})\n    _GRADER[0] = bool(meta.get('degDoc'))\n    digits = meta.get('digits')\n    _CIFRE[0] = digits if isinstance(digits, int) and 1 <= digits <= 15 else None\n    try:\n        r = _fmt(st, ns)\n        # \"Gem som\": vis de faktisk gemte navne med blokkens valgte præcision.\n        if meta.get('saved') and isinstance(r, dict):\n            vals = {}\n            for n in meta['saved']:\n                if n in ns and n not in _BASE:\n                    try:\n                        sv = sympify(ns[n])\n                        if isinstance(sv, sympy.Symbol):\n                            continue\n                        vals[n] = tex(sv)\n                    except Exception:\n                        pass\n            r['savedVals'] = vals\n        return r\n    finally:\n        _GRADER[0] = False\n        _CIFRE[0] = None\n\n\ndef _fmt(st, ns):\n    kind, meta = st['kind'], st.get('meta', {})\n    if kind == 'define':\n        val = ns[meta['name']]\n        if meta['def'] == 'fn':\n            return {'latex': tex(val.expr), 'py': _py(val)} if not hasattr(val, 'variables') else {'latex': tex(val.expr), 'py': '%s(%s) = %s' % (meta['name'], meta.get('v', 'x'), _py(val.expr))}\n        v = sympify(val)\n        if v.has(sympy.zoo) or v.has(sympy.nan):\n            raise ZeroDivisionError()\n        if v.is_number and not meta.get('dec') and (_kæmpe(tex(v)) or v.has(sympy.sin, sympy.cos, sympy.tan)):\n            return {'latex': tex(v.evalf(15)), 'py': _py(v), 'approx': True, 'long': True}\n        if v.is_number and v.is_real and not v.is_Rational and not v.has(sympy.Float) and not meta.get('dec'):\n            return {'latex': tex(v), 'py': _py(v), 'dec': tex(v.evalf(10))}\n        if meta.get('dec') and v.is_number:\n            return {'latex': tex(v.evalf(15)), 'py': _py(v), 'approx': not _kort(v.evalf(15))}\n        r = {'latex': tex(v), 'py': _py(v), 'approx': bool(v.has(sympy.Float)) and not _kort(v)}\n        if _brøk(v):\n            r['dec'] = tex(v.evalf(15))\n        return r\n    if kind == 'value':\n        v = ns[meta['res']]\n        if type(v).__name__ == 'CirkelLigning':\n            v0, r2, x0, y0 = v\n            if r2 > 0:\n                rr = sympy.sqrt(r2)\n                rt = tex(rr) + (r' \\approx ' + tex(rr.evalf(15)) if not rr.is_Rational else '')\n                led = lambda z, z0: tex(z) + '^{2}' if z0 == 0 else r'\\left(' + tex(z - z0) + r'\\right)^{2}'\n                venstre = led(sympy.Symbol('x'), x0) + ' + ' + led(sympy.Symbol('y'), y0)\n                return {'latex': venstre + '=' + tex(r2) + r'\\quad\\text{centrum }\\left(' + tex(x0) + r';\\ ' + tex(y0) + r'\\right)\\text{, radius }' + rt, 'py': _py(v0) + ' = ' + _py(r2)}\n            return {'latex': tex(v0) + '=' + tex(r2) + (r'\\quad\\text{ingen cirkel}' if r2 < 0 else r'\\quad\\text{kun punktet }\\left(' + tex(x0) + r';\\ ' + tex(y0) + r'\\right)'), 'py': _py(v0)}\n        if isinstance(v, tuple):\n            return {'latex': tex(v[0]) + '=' + tex(v[1]), 'py': _py(v)}\n        v = sympify(v)\n        if v.has(sympy.Float) and v.is_number:\n            v = v.evalf(15)\n        if v.has(sympy.zoo) or v.has(sympy.nan):\n            raise ZeroDivisionError()\n        # en vektor med en uskøn eksakt koordinat (fx fra tan(69°)) vises med decimaltal\n        if isinstance(v, sympy.MatrixBase) and not v.free_symbols and any(_uskøn(tex(e)) or e.has(sympy.Float) for e in v):\n            v = type(v)(v.evalf(15)) if isinstance(v, _BASE['Vektor']) else v.evalf(15)\n            return {'latex': tex(v), 'py': _py(v), 'approx': not all(_kort(e) for e in v)}\n        r = {'latex': tex(v), 'py': _py(v)}\n        # ulæseligt langt eksakt tal: vis decimaltallet i stedet\n        if v.is_number and _kæmpe(r['latex']):\n            try:\n                return {'latex': tex(v.evalf(15)) + (r'^{\\circ}' if meta.get('deg') else ''), 'py': _py(v), 'approx': True, 'long': True}\n            except Exception:\n                pass\n        if meta.get('deg') and v.is_number and (v.has(sympy.asin, sympy.acos, sympy.atan) or not v.is_Rational):\n            try:\n                x = v.evalf(15)\n                if x.is_real:\n                    return {'latex': tex(x) + r'^{\\circ}', 'py': _py(v), 'approx': not _kort(x)}\n            except Exception:\n                pass\n        if meta.get('deg'):\n            r = {'latex': tex(v) + r'^{\\circ}', 'py': _py(v)}\n            if v.is_number and not v.is_Rational and not v.has(sympy.Float):\n                r['dec'] = tex(v.evalf(15), 5) + r'^{\\circ}'\n            elif v.has(sympy.Float) and not _kort(v):\n                r['approx'] = True\n            return r\n        if isinstance(v, sympy.Interval):\n            r['approx'] = bool(v.has(sympy.Float)) and not (_kort(v.start.evalf(15)) and _kort(v.end.evalf(15)))\n            return r\n        if v.has(sympy.LambertW):\n            r['latex'] = tex(v.evalf(15)); r['approx'] = True\n        elif v.has(sympy.Float) and not _kort(v):\n            r['approx'] = True\n        elif _brøk(v):\n            r['dec'] = tex(v.evalf(15))\n        elif v.is_number and v.is_real and not v.is_Rational and not v.has(sympy.Float):\n            try:\n                if _uskøn(r['latex']):\n                    return {'latex': tex(v.evalf(15)), 'py': _py(v), 'approx': True, 'long': True}\n                r['dec'] = tex(v.evalf(15), 5)\n            except Exception:\n                pass\n        return r\n    if kind == 'inline':\n        v = sympify(ns[meta['res']])\n        if v.has(sympy.zoo) or v.has(sympy.nan):\n            raise ZeroDivisionError()\n        r = {'latex': tex(v), 'py': _py(v)}\n        try:\n            if v.is_number:\n                r['approx'] = tex(v.evalf(15), 4)\n                r['exact'] = (not v.has(sympy.Float) and len(r['latex']) <= 14 and (v.is_Rational or v.is_Integer)) or (v.has(sympy.Float) and _kort(v))\n                r['integer'] = bool(v.is_Integer)\n        except Exception:\n            pass\n        return r\n    if kind == 'ode':\n        # løsningerne til en differentialligning: y(t) = 1,8·e^(−0,03t)\n        sols, approx = [], False\n        for s in ns[meta['res']]:\n            lhs = tex(s.lhs).replace(r'{\\left(', '(').replace(r' \\right)}', ')')\n            rhs = s.rhs\n            if rhs.has(sympy.Float) and not _kort(rhs):\n                approx = True\n            sols.append(lhs + ' = ' + tex(rhs))\n        return {'solutions': sols, 'approx': approx, 'py': _py(ns[meta['res']])}\n    if kind == 'solve':\n        res = ns[meta['res']]\n        x = sympy.Symbol(meta.get('vname') or meta['v'], real=True)\n        if isinstance(res, sympy.Set):\n            if res is sympy.S.EmptySet:\n                return {'solutions': [], 'py': _py(res)}\n            if res is sympy.S.Reals:\n                return {'latex': tex(x) + r' \\in \\mathbb{R}' + r'\\quad\\text{(alle tal)}', 'py': _py(res)}\n            if isinstance(res, sympy.FiniteSet):\n                res = list(res)\n            else:\n                g = _generel(res, x, meta.get('deg'), meta.get('dec'))\n                if g is not None:\n                    return {'latex': g, 'general': True, 'py': _py(res)}\n                return {'latex': _ulighed_tex(res, x), 'py': _py(res)}\n        if isinstance(res, (list, tuple)):\n            sols, approx = [], False\n            def nøgle(s):\n                try:\n                    return float(sympy.re(sympy.N(s)))\n                except Exception:\n                    return 0.0\n            if all(not isinstance(s, dict) for s in res):\n                res = sorted(res, key=nøgle)\n            for s in res:\n                if isinstance(s, dict):\n                    dele = []\n                    for k, v in s.items():\n                        v = sympify(v)\n                        t = tex(v)\n                        if v.has(sympy.Float) and not _kort(v):\n                            approx = True\n                        elif v.is_number and v.is_real and not v.is_Rational and not v.has(sympy.Float):\n                            if _uskøn(t):\n                                t = tex(v.evalf(15)); approx = True\n                            else:\n                                t += r' \\approx ' + tex(v.evalf(15))\n                        elif _brøk(v):\n                            t += r' \\approx ' + tex(v.evalf(15))\n                        dele.append(f'{tex(k)} = {t}')\n                    sols.append(' ,\\\\ '.join(dele))\n                    continue\n                s = sympify(s)\n                if s.has(sympy.LambertW) or (s.is_number and _kæmpe(tex(s))):\n                    s = s.evalf(15)\n                if s.has(sympy.Float) and not _kort(s):\n                    approx = True\n                elif s.is_Add:\n                    s = sympy.together(s)\n                # tal-løsninger skrives med konstanten først, så de står ens: 2 − √10/2 og 2 + √10/2\n                grad = r'^{\\circ}' if meta.get('deg') else ''\n                t = tex(s, order='none' if s.is_number else None) + grad\n                # en lang eller trigonometrisk eksakt løsning får også et decimaltal: c = √2·√(65 − 63cos 52°) ≈ 7,241\n                try:\n                    if s.is_number and s.is_real and not s.is_Rational and not s.has(sympy.Float) and _uskøn(t) and not s.has(sympy.sin, sympy.cos, sympy.tan):\n                        t = tex(s.evalf(15)) + grad; approx = True\n                    elif s.is_number and s.is_real and not s.is_Rational and not s.has(sympy.Float) and (len(t) > 24 or s.has(sympy.sin, sympy.cos, sympy.tan, sympy.log)):\n                        t += r' \\approx ' + tex(s.evalf(15), 4) + grad\n                    elif _brøk(s):\n                        t += r' \\approx ' + tex(s.evalf(15), 4) + grad\n                except Exception:\n                    pass\n                sols.append(t)\n            return {'solutions': sols, 'approx': approx, 'py': _py(res)}\n        if isinstance(res, sympy.logic.boolalg.Boolean) and not isinstance(res, sympy.logic.boolalg.BooleanAtom):\n            try:\n                return {'latex': _ulighed_tex(res.as_set(), x), 'py': _py(res)}\n            except Exception:\n                pass\n        if res is True or res == S.true:\n            return {'latex': '\\\\text{sand for alle }' + tex(sympy.Symbol(meta['v']))}\n        if res is False or res == S.false:\n            return {'solutions': []}\n        return {'latex': tex(res)}\n    if kind == 'graph':\n        if meta.get('bars'):\n            søjler = [(int(k), float(p)) for k, p in ns['søjler']]\n            # ved store n vises kun søjler, der kan ses\n            if len(søjler) > 61:\n                søjler = [q for q in søjler if q[1] > 1e-4]\n            return {'bars': søjler, 'labels': []}\n        fig = _figurer(ns.get('figurer') or [], ns) if meta.get('figurer') else None\n        if meta.get('auto'):\n            if ns['fns']:\n                ns['ts'], ns['kurver'] = _auto_interval(ns['fns'], ns['punkt'], meta.get('tid'))\n            else:\n                ns['ts'], ns['kurver'] = [], []\n            if fig:\n                # vinduet skal vise punkterne og cirklerne (og funktionernes vigtige steder)\n                a, b = fig['xr']\n                if ns['ts']:\n                    a, b = min(a, ns['ts'][0]), max(b, ns['ts'][-1])\n                n = 300\n                ns['ts'] = [a + (b - a) * i / n for i in range(n + 1)]\n                ns['kurver'] = [[ns['punkt'](fn, t) for t in ns['ts']] for fn in ns['fns']]\n        kurver = ns['kurver']\n        udtryk = ns['udtryk']\n        v = ns[meta['v']]\n        warn = []\n        for u in udtryk:\n            fri = sorted(str(s) for s in getattr(sympify(u), 'free_symbols', set()) if s != v)\n            if fri:\n                warn.append(', '.join(fri))\n        ts = [float(t) for t in ns['ts']]\n        r = {'ts': ts, 'curves': kurver, 'labels': [tex(u) for u in udtryk], 'warn': warn}\n        if ns.get('arealer'):\n            # de skraverede arealer: grafernes punkter mellem grænserne\n            r['areas'] = []\n            for top, bund, a0, b0, farve in ns['arealer']:\n                xx = [a0 + (b0 - a0) * i / 120 for i in range(121)]\n                øv, nd = [ns['punkt'](top, q) for q in xx], [ns['punkt'](bund, q) for q in xx]\n                # integralets værdi (Simpsons formel med 120 delintervaller), vises i forklaringen\n                try:\n                    d = [u - w for u, w in zip(øv, nd)]\n                    værdi = (b0 - a0) / 360 * (d[0] + d[-1] + sum((4 if i % 2 else 2) * d[i] for i in range(1, 120)))\n                except TypeError:\n                    værdi = None\n                r['areas'].append({'c': farve, 'top': [[q, y] for q, y in zip(xx, øv)], 'bot': [[q, y] for q, y in zip(xx, nd)], 'value': værdi})\n        if fig:\n            a, b = (ts[0], ts[-1]) if ts else fig['xr']\n            ya, yb = meta.get('ya'), meta.get('yb')\n            # kun linjer (ingen punkter eller cirkler): y-aksen følger funktionerne, ellers ±10\n            fyr = fig['yr'] or ([-10.0, 10.0] if not kurver else [min(v for k in kurver for v in k if v is not None), max(v for k in kurver for v in k if v is not None)])\n            c, d = (ya if ya is not None else fyr[0]), (yb if yb is not None else fyr[1])\n            if fig['flader']:\n                # en flade i 3D: vinduet er x- og y-aksens intervaller (y som x, hvis eleven ikke har valgt)\n                c3, d3 = (ya, yb) if ya is not None and yb is not None else (a, b)\n                r['figs'] = {'points': [], 'lines': [], 'arrows': [], 'yr': None, 'equal': False, 'surface': _flade(fig['flader'], a, b, c3, d3)}\n                r['labels'] += ['' for _ in fig['flader']]\n                r['nfig'] = len(fig['flader'])\n                return r\n            felt_kurver, gitter = [], None\n            if fig['felter']:\n                # hældningsfelt: y-aksen følger løsningskurverne (medmindre eleven har valgt den), og akserne har hver sin enhed\n                felt_kurver, gitter, c, d = _hældningsfelt(fig['felter'], a, b, ya, yb)\n            r['figs'] = {'points': fig['punkter'], 'lines': fig['linjer'] + felt_kurver + [{'i': i, 'pts': k} for i, e in fig['ligninger'] for k in _ligning_kurver(e, ns, a, b, c, d)],\n                         'yr': [c, d] if fig['yr'] or gitter else None, 'equal': bool(fig['yr']) and not gitter, 'arrows': fig['pile']}\n            if gitter:\n                r['figs']['field'] = gitter\n            n = len(fig['linjer']) + len(fig['ligninger']) + len(fig['pile']) + len(fig['felter'])\n            r['labels'] += ['' for _ in range(n)]\n            r['nfig'] = n\n        if meta.get('marks') and not warn:\n            a = meta.get('xa', ts[0]) if meta.get('xa') is not None else ts[0]\n            b = meta.get('xb', ts[-1]) if meta.get('xb') is not None else ts[-1]\n            r['marks'] = _aflæs(ns['fns'], meta['marks'], a, b)\n        return r\n    if kind == 'table':\n        # (med frekvenser kendes antallet af observationer ikke: n er None)\n        antal = None if ns.get('antal') is None else int(ns['antal'])\n        if meta.get('model') == 'qq':\n            return {'qq': [[float(x), float(z)] for x, z in zip(ns['data'], ns['fraktiler'])], 'mean': float(ns['middel']), 's': float(ns['spredning']), 'n': antal, 'R2': float(ns['R2']), 'w': meta.get('w')}\n        if meta.get('model') == 'stat':\n            return {'stat': {'n': antal, 'mean': float(ns['middel']), 's': float(ns['spredning']), 'kv': ns['kv'], 'w': meta.get('w')}}\n        if meta.get('model') == 'sum':\n            return {'kum': [float(k) for k in ns['kumuleret']], 'pts': [[float(a), float(b)] for a, b in ns['punkter']], 'py': _py(ns[meta['f']]),\n                    'ivs': [[float(a), float(b)] for a, b in ns['intervaller']], 'pct': [float(p) for p in ns['frekvenser']],\n                    'n': antal, 'kv': ns['kv']}\n        r = {'params': [_num(ns[p]) for p in meta['params']], 'R2': _num(ns[meta['R2']]), 'py': _py(ns[meta['f']]),\n             'latex': tex(ns[meta['f']](ns[meta['v']]), 4)}\n        rs = meta.get('resid')\n        if rs:\n            r['resid'] = [float(x) for x in ns[rs['res']]]\n            r['s'] = float(ns[rs['s']])\n            r['andel'] = float(ns[rs['andel']])\n            r['kv'] = ns[rs['kv']]\n            if rs.get('ki'):\n                r['ki'] = [float(k) for k in ns[rs['ki']]]\n        return r\n    if kind == 'python':\n        return {}\n    return {}\n\n\ndef _cirkel(e, x, y):\n    # (centrum, radius) hvis ligningen er en cirkel: x² og y² med samme koefficient og intet xy-led\n    try:\n        p = sympy.Poly(sympy.expand(e.lhs - e.rhs), x, y)\n    except Exception:\n        return None\n    if p.total_degree() != 2:\n        return None\n    A = p.coeff_monomial(x ** 2)\n    if A == 0 or p.coeff_monomial(y ** 2) != A or p.coeff_monomial(x * y) != 0:\n        return None\n    cx, cy = -p.coeff_monomial(x) / (2 * A), -p.coeff_monomial(y) / (2 * A)\n    r2 = cx ** 2 + cy ** 2 - p.coeff_monomial(1) / A\n    return (float(cx), float(cy), math.sqrt(float(r2))) if float(r2) > 0 else None\n\n\ndef _figurer(figurer, ns):\n    # punkter, polygoner og ligninger fra grafens felter, og et vindue, der viser dem\n    x, y = sympy.Symbol('x', real=True), sympy.Symbol('y', real=True)\n    punkter, linjer, ligninger, pile, xs, ys = [], [], [], [], [], []\n    nr = 0  # nummeret på den tegnede figur (til farve og forklaring)\n    felter, flader = [], []\n    for f in figurer:\n        if f[0] == 'flade':\n            # en funktion af to variable: højderne regnes ud, når vinduet kendes\n            flader.append({'i': nr, 'fn': sympy.lambdify((f[3], f[4]), f[2], 'math')})\n            nr += 1\n            continue\n        if f[0] == 'felt':\n            # et hældningsfelt: y′ = F(t, y) regnes ud, når vinduet kendes (se _hældningsfelt)\n            lig, fx, var, punkter_ = f[2], f[3], f[4], f[5]\n            D, Y = sympy.Dummy('D'), sympy.Dummy('Y')\n            e = (lig.lhs - lig.rhs).subs(fx.diff(var), D).subs(fx, Y)\n            F = sympy.solve(e, D)\n            if len(F) != 1:\n                raise ValueError('Skriv differentialligningen, så den kan løses for ' + str(fx.func) + '′, fx ' + str(fx.func) + '′ = x·(' + str(fx.func) + ' + 1)')\n            felter.append({'i': nr, 'fn': sympy.lambdify((var, Y), F[0], 'math'), 'punkter': [(float(a), float(b)) for a, b in punkter_]})\n            nr += 1\n            continue\n        if f[0] == 'bane':\n            # en parameterkurve s⃗(t) for t i [a; b]: punkterne, med et hul hvor kurven ikke er defineret\n            u, var, a0, b0 = f[2], f[3], float(f[4]), float(f[5])\n            # en linje P + u·r⃗ (førstegrads i parameteren) tegnes som en linje gennem vinduet, som de andre figurer bestemmer\n            # (men med et valgt interval, fx −1 ≤ u ≤ 1, kun for det interval)\n            valgt = len(f) > 6 and f[6]\n            if not valgt and all(sympy.diff(k, var, 2) == 0 for k in u) and any(sympy.diff(k, var) != 0 for k in u):\n                x, y = sympy.Symbol('x', real=True), sympy.Symbol('y', real=True)\n                P, r = [k.subs(var, 0) for k in u], [sympy.diff(k, var) for k in u]\n                ligninger.append((nr, sympy.Eq(-r[1] * (x - P[0]) + r[0] * (y - P[1]), 0)))\n                nr += 1\n                xs.append(float(P[0])); ys.append(float(P[1]))\n                continue\n            kx, ky = sympy.lambdify(var, u[0], 'math'), sympy.lambdify(var, u[1], 'math')\n            pts = []\n            for i in range(801):\n                tt = a0 + (b0 - a0) * i / 800\n                try:\n                    p = (float(kx(tt)), float(ky(tt)))\n                    if not (math.isfinite(p[0]) and math.isfinite(p[1])):\n                        raise ValueError\n                    pts.append(p)\n                    xs.append(p[0]); ys.append(p[1])\n                except Exception:\n                    if pts and pts[-1] != (None, None):\n                        pts.append((None, None))\n            linjer.append({'i': nr, 'pts': pts, 'dir': True})\n            nr += 1\n            continue\n        if f[0] == 'pil':\n            # en vektor: fra origo (a⃗) eller fra A til B (AB⃗)\n            q = f[2]\n            if len(q) == 1:\n                fra, til = (0.0, 0.0), (float(q[0][0]), float(q[0][1]))\n            else:\n                fra, til = (float(q[0][0]), float(q[0][1])), (float(q[1][0]), float(q[1][1]))\n            pile.append({'i': nr, 'from': fra, 'to': til, 'label': f[1]})\n            nr += 1\n            xs += [fra[0], til[0]]; ys += [fra[1], til[1]]\n            continue\n        if f[0] in ('punkt', 'polygon'):\n            pkt = [(float(q[0]), float(q[1])) for q in f[2]]\n            punkter += [[n, px, py] for n, (px, py) in zip(f[1], pkt) if not any(q[0] == n for q in punkter)]\n            xs += [q[0] for q in pkt]; ys += [q[1] for q in pkt]\n            # et punkt (A) eller en polygon (A;B;C)\n            if len(pkt) > 1:\n                linjer.append({'i': nr, 'pts': pkt + ([pkt[0]] if len(pkt) > 2 else [])})\n                nr += 1\n        else:\n            e = f[1]\n            ligninger.append((nr, e))\n            nr += 1\n            c = _cirkel(e, x, y)\n            if c:\n                xs += [c[0] - c[2], c[0] + c[2]]; ys += [c[1] - c[2], c[1] + c[2]]\n    if not xs:\n        xr = [-10.0, 10.0]\n        # et hældningsfelt: fra t = 0, når løsningskurverne starter ved t ≥ 0 (en tid)\n        t0 = [p[0] for fe in felter for p in fe['punkter']]\n        if t0:\n            xr = [0.0, max(10.0, 2 * max(t0))] if min(t0) >= 0 else [min(t0) - 10.0, max(t0) + 10.0]\n        if flader:\n            xr = [-5.0, 5.0]\n        return {'punkter': punkter, 'linjer': linjer, 'ligninger': ligninger, 'pile': pile, 'felter': felter, 'flader': flader, 'xr': xr, 'yr': None}\n    # origo med, når det er tæt på (et koordinatsystem med A i (0, 0))\n    a, b, c, d = min(xs + [0]), max(xs + [0]), min(ys + [0]), max(ys + [0])\n    pad = max(b - a, d - c) * 0.15 or 1\n    return {'punkter': punkter, 'linjer': linjer, 'ligninger': ligninger, 'pile': pile, 'felter': felter, 'flader': flader, 'xr': [a - pad, b + pad], 'yr': [c - pad, d + pad]}\n\n\ndef _flade(flader, a, b, c, d, n=30):\n    # højderne z = f(x, y) i et gitter over [a; b] × [c; d] (None hvor f ikke er defineret), og z-aksens interval\n    fe = flader[0]\n    xs = [a + (b - a) * i / n for i in range(n + 1)]\n    ys = [c + (d - c) * j / n for j in range(n + 1)]\n    z = []\n    for x in xs:\n        række = []\n        for y in ys:\n            try:\n                v = fe['fn'](x, y)\n                v = float(v) if not isinstance(v, complex) else None\n                række.append(v if v is not None and math.isfinite(v) else None)\n            except Exception:\n                række.append(None)\n        z.append(række)\n    alle = sorted(v for r in z for v in r if v is not None)\n    if not alle:\n        raise ValueError('Funktionen er ikke defineret i vinduet – vælg et andet interval for akserne')\n    lo, hi = alle[int(len(alle) * 0.01)], alle[max(0, int(len(alle) * 0.99) - 1)]\n    if alle[-1] - alle[0] <= 3 * (hi - lo or 1):\n        lo, hi = alle[0], alle[-1]\n    if hi - lo < 1e-9:\n        lo, hi = lo - 1, hi + 1\n    return {'i': fe['i'], 'x': [a, b], 'y': [c, d], 'z': z, 'zr': [lo, hi]}\n\n\ndef _rk4(fn, x0, y0, x1, n=400, grænse=1e9):\n    # en løsningskurve fra (x0, y0) til x1 med Runge–Kutta (4. orden); stopper, hvis kurven forlader det fornuftige\n    pts, h, x, y = [(x0, y0)], (x1 - x0) / n, x0, y0\n    for _ in range(n):\n        try:\n            k1 = fn(x, y); k2 = fn(x + h / 2, y + h / 2 * k1); k3 = fn(x + h / 2, y + h / 2 * k2); k4 = fn(x + h, y + h * k3)\n            y = y + h / 6 * (k1 + 2 * k2 + 2 * k3 + k4)\n        except (ValueError, ZeroDivisionError, OverflowError, TypeError):\n            break\n        x = x + h\n        if isinstance(y, complex) or not math.isfinite(y) or abs(y) > grænse:\n            break\n        pts.append((x, y))\n    return pts\n\n\ndef _hældningsfelt(felter, a, b, c=None, d=None):\n    # løsningskurverne gennem punkterne (begge veje) og hældningerne i et gitter over vinduet [a; b] × [c; d]\n    # (uden y-grænser: y-aksen følger løsningskurverne)\n    kurver = []\n    for fe in felter:\n        for x0, y0 in fe['punkter']:\n            venstre = _rk4(fe['fn'], x0, y0, a) if a < x0 else []\n            højre = _rk4(fe['fn'], x0, y0, b) if b > x0 else []\n            kurver.append({'i': fe['i'], 'pts': list(reversed(venstre))[:-1] + højre if venstre else højre})\n    if c is None or d is None:\n        ys = sorted(y for k in kurver for _, y in k['pts'])\n        if ys:\n            lo, hi = ys[int(len(ys) * 0.02)], ys[max(0, int(len(ys) * 0.98) - 1)]\n            lo, hi = min(lo, ys[0]) if ys[-1] - ys[0] < 3 * (hi - lo or 1) else lo, max(hi, ys[-1]) if ys[-1] - ys[0] < 3 * (hi - lo or 1) else hi\n            pad = (hi - lo) * 0.15 or 1\n            c0, d0 = lo - pad, hi + pad\n        else:\n            c0, d0 = -10.0, 10.0\n        c = c0 if c is None else c\n        d = d0 if d is None else d\n    gitter = []\n    nx, ny = 21, 15\n    for fe in felter:\n        pts = []\n        for i in range(nx):\n            for j in range(ny):\n                x, y = a + (b - a) * (i + 0.5) / nx, c + (d - c) * (j + 0.5) / ny\n                try:\n                    s = float(fe['fn'](x, y))\n                    if math.isfinite(s):\n                        pts.append([x, y, s])\n                except Exception:\n                    pass\n        gitter.append({'i': fe['i'], 'pts': pts})\n    return kurver, gitter, c, d\n\n\ndef _ligning_kurver(e, ns, a, b, c, d):\n    # en ligning i x og y som kurver (lister af punkter) i vinduet [a; b] × [c; d]\n    x, y = sympy.Symbol('x', real=True), sympy.Symbol('y', real=True)\n    k = _cirkel(e, x, y)\n    if k:\n        cx, cy, r = k\n        return [[(cx + r * math.cos(2 * math.pi * i / 240), cy + r * math.sin(2 * math.pi * i / 240)) for i in range(241)]]\n    try:\n        p = sympy.Poly(sympy.expand(e.lhs - e.rhs), x, y)\n        if p.total_degree() == 1:\n            A, B, C = (float(p.coeff_monomial(m)) for m in (x, y, 1))\n            if abs(B) > 1e-12:\n                return [[(a, -(A * a + C) / B), (b, -(A * b + C) / B)]]\n            return [[(-C / A, c), (-C / A, d)]]  # lodret linje\n    except Exception:\n        pass\n    ud = []\n    for g in sympy.solve(e, y):\n        fn = sympy.lambdify(x, g, 'math')\n        stykke = []\n        for i in range(301):\n            t = a + (b - a) * i / 300\n            v = _BASE['punkt'](fn, t)\n            if v is None:\n                if len(stykke) > 1:\n                    ud.append(stykke)\n                stykke = []\n            else:\n                stykke.append((t, v))\n        if len(stykke) > 1:\n            ud.append(stykke)\n    return ud\n\n\ndef _pæn(x, op):\n    # afrund et interval-endepunkt til et pænt tal\n    trin = 10 ** math.floor(math.log10(max(abs(x), 1)))\n    trin = trin / 2 if trin >= 1 else 1\n    return op(x / trin) * trin\n\n\ndef _auto_interval(fns, punkt, tid=False):\n    # Find nulpunkter, toppunkter, vendepunkter og kanter af definitionsmængden på [-50; 50] og vis dem med lidt luft.\n    # Flader en kurve ud (henfald, logistisk vækst), kommer den del med, hvor den stadig ændrer sig.\n    xs = [-50 + i * 0.05 for i in range(2001)]\n    pts, rolig = [], []\n    alle = [[punkt(fn, x) for x in xs] for fn in fns]\n    for ys in alle:\n        ok = [x for x, y in zip(xs, ys) if y is not None]\n        def spring(i):\n            # et fortegnsskift ved en lodret asymptote (stort spring i forhold til naboerne) er ikke et nulpunkt\n            nab = [abs(ys[k + 1] - ys[k]) for k in (i - 2, i) if 0 <= k < len(ys) - 1 and ys[k] is not None and ys[k + 1] is not None]\n            return nab and abs(ys[i] - ys[i - 1]) > 50 * max(nab + [1e-300])\n        for i in range(1, len(xs) - 1):\n            a, b, c = ys[i - 1], ys[i], ys[i + 1]\n            if a is None or b is None:\n                continue\n            if b == 0 or (a * b < 0 and not spring(i)):\n                pts.append(xs[i])\n            if c is not None and (b - a) * (c - b) < 0 and not spring(i) and not spring(i + 1):\n                pts.append(xs[i])\n        # vendepunkter\n        d2 = [None] + [(ys[i + 1] - 2 * ys[i] + ys[i - 1]) if None not in (ys[i - 1], ys[i], ys[i + 1]) else None for i in range(1, len(xs) - 1)] + [None]\n        skala = max((abs(y) for y in ys if y is not None and math.isfinite(y)), default=1) or 1\n        for i in range(2, len(xs) - 2):\n            p, q = d2[i], d2[i + 1]\n            if p is not None and q is not None and p * q < 0 and max(abs(p), abs(q)) > 1e-10 * skala and abs(ys[i]) < 1e6 * (1 + min(abs(y) for y in ys if y is not None)):\n                pts.append(xs[i])\n        if ok and ok[0] > -50 + 1e-9:\n            pts.append(ok[0])\n        if ok and ok[-1] < 50 - 1e-9:\n            pts.append(ok[-1])\n        rolig.append(ys)\n    # skæringspunkter mellem graferne skal også med\n    for i in range(len(alle)):\n        for j in range(i + 1, len(alle)):\n            for k in range(1, len(xs)):\n                a0, a1, b0, b1 = alle[i][k - 1], alle[i][k], alle[j][k - 1], alle[j][k]\n                if None in (a0, a1, b0, b1):\n                    continue\n                d0, d1 = a0 - b0, a1 - b1\n                if d1 == 0 or d0 * d1 < 0:\n                    pts.append(xs[k])\n    if len(pts) > 8:\n        nære = [p for p in pts if -10 <= p <= 10]\n        pts = nære or pts[:8]\n    ekstra = []\n    if pts:\n        # kurver, der flader ud mod en side: tag med, indtil 80 % af ændringen er sket\n        for ys in rolig:\n            ekstra += _udfladning(xs, ys, min(pts), max(pts))\n    alle_pts = pts + ekstra\n    if alle_pts:\n        lo, hi = min(alle_pts), max(alle_pts)\n        luft = max(1.5, (0.15 if ekstra else 0.35) * (hi - lo))\n        lo, hi = lo - luft, hi + luft\n        if tid and lo < 0 <= min(pts):\n            lo = 0.0\n        if lo > 0 and lo < 0.35 * (hi - lo):\n            lo = 0.0\n        lo, hi = _pæn(lo, math.floor), _pæn(hi, math.ceil)\n    else:\n        lo, hi = (0.0, 20.0) if tid else (-10.0, 10.0)\n    if hi - lo < 2:\n        lo, hi = lo - 1, hi + 1\n    ts = [lo + (hi - lo) * i / 300 for i in range(301)]\n    return ts, [[punkt(fn, t) for t in ts] for fn in fns]\n\n\ndef _udfladning(xs, ys, fra, til):\n    # Hvor langt ud skal en kurve, der flader ud, vises? Til 80 % af dens ændring efter det sidste kendte punkt.\n    ud = []\n    fin = [(x, y) for x, y in zip(xs, ys) if y is not None and math.isfinite(y)]\n    if len(fin) < 10:\n        return ud\n    # sammenlign med hældningen der, hvor der sker noget (mellem de kendte punkter) – ikke ved en asymptote\n    inde = [abs(fin[i + 1][1] - fin[i][1]) for i in range(len(fin) - 1) if fra - 1 <= fin[i][0] <= til + 1]\n    inde.sort()\n    top = (inde[len(inde) // 2] if inde else 0) or 1   # medianen: et spring ved en asymptote tæller ikke\n    for side in (1, -1):\n        stykke = [(x, y) for x, y in fin if (x >= til if side == 1 else x <= fra)]\n        if side == -1:\n            stykke = stykke[::-1]\n        if len(stykke) < 10:\n            continue\n        ende = abs(stykke[-1][1] - stykke[-2][1])\n        if ende > 0.03 * top:\n            continue\n        samlet = sum(abs(stykke[i + 1][1] - stykke[i][1]) for i in range(len(stykke) - 1))\n        if samlet <= 0:\n            continue\n        acc = 0\n        for i in range(len(stykke) - 1):\n            acc += abs(stykke[i + 1][1] - stykke[i][1])\n            if acc >= 0.8 * samlet:\n                ud.append(stykke[i + 1][0])\n                break\n    return ud\n\n\ndef _aflæs(fns, marks, a, b, n=4000):\n    # Punkter, der aflæses på grafen: maksimum, minimum, nulpunkter og skæringer (numerisk)\n    ud = []\n    def værdi(i, j):\n        f, g = fns[i], (fns[j] if j is not None else None)\n        def v(x):\n            y = _BASE['punkt'](f, x)\n            if y is None or g is None:\n                return y\n            z = _BASE['punkt'](g, x)\n            return None if z is None else y - z\n        return v\n    for m in marks:\n        dele = str(m).split(':')\n        kind = dele[0]\n        try:\n            i = int(dele[1]) if len(dele) > 1 else 0\n            j = int(dele[2]) if len(dele) > 2 else None\n        except ValueError:\n            continue\n        if i >= len(fns) or (j is not None and j >= len(fns)) or (kind == 'isect' and j is None):\n            continue\n        v = værdi(i, j if kind == 'isect' else None)\n        xs = [a + (b - a) * k / n for k in range(n + 1)]\n        ys = [v(x) for x in xs]\n        fundet = []\n        if kind in ('zero', 'isect'):\n            for k in range(1, n + 1):\n                y0, y1 = ys[k - 1], ys[k]\n                if y0 is None or y1 is None:\n                    continue\n                if y0 == 0:\n                    fundet.append(xs[k - 1]); continue\n                if y0 * y1 < 0:\n                    lo, hi = xs[k - 1], xs[k]\n                    for _ in range(70):\n                        mid = (lo + hi) / 2\n                        ym = v(mid)\n                        if ym is None:\n                            break\n                        if (ym < 0) == (y0 < 0):\n                            lo = mid\n                        else:\n                            hi = mid\n                    r = (lo + hi) / 2\n                    ym = v(r)\n                    if ym is not None and abs(ym) < 1e-6 * max(1, abs(y0), abs(y1)):\n                        fundet.append(r)\n        elif kind in ('max', 'min'):\n            sgn = 1 if kind == 'max' else -1\n            for k in range(1, n):\n                y0, y1, y2 = ys[k - 1], ys[k], ys[k + 1]\n                if None in (y0, y1, y2):\n                    continue\n                if sgn * (y1 - y0) >= 0 and sgn * (y1 - y2) > 0:\n                    lo, hi = xs[k - 1], xs[k + 1]\n                    g = (math.sqrt(5) - 1) / 2\n                    for _ in range(80):\n                        c, d = hi - g * (hi - lo), lo + g * (hi - lo)\n                        fc, fd = v(c), v(d)\n                        if fc is None or fd is None:\n                            break\n                        if sgn * fc > sgn * fd:\n                            hi = d\n                        else:\n                            lo = c\n                    fundet.append((lo + hi) / 2)\n        for x in fundet[:6]:\n            # Et nulpunkt ligger på førsteaksen. Vis ikke flydende regnestøj som y-værdi.\n            y = 0.0 if kind == 'zero' else _BASE['punkt'](fns[i], x)\n            if y is not None:\n                ud.append({'k': kind, 'i': i, 'j': j, 'x': x, 'y': y})\n    return ud\n\n\ndef run(steps_json):\n    steps = json.loads(steps_json)\n    ns = dict(_BASE)\n    out = []\n    for st in steps:\n        r = {'id': st['id']}\n        buf = io.StringIO()\n        try:\n            target = dict(ns) if st['kind'] == 'python' else ns\n            with contextlib.redirect_stdout(buf):\n                exec(compile(st['code'], '<blok>', 'exec'), target)\n            r.update(fmt(st, target))\n        except Exception as e:\n            r['error'] = dansk_fejl(e)\n            if st['kind'] == 'python':\n                tb = traceback.format_exc().splitlines()\n                r['trace'] = '\\n'.join(l for l in tb if '<blok>' in l or not l.startswith('  File'))[-800:]\n        p = buf.getvalue()\n        if p:\n            r['stdout'] = p[-6000:]\n        out.append(r)\n    return json.dumps(out)\n\n\ndef varm():\n    # Første brug af solve, simplify, diff, integrate og lambdify henter mange moduler; gør det, mens CAS starter\n    ns = dict(_BASE)\n    exec('''\nx, a, b = symbols('x a b', real=True)\nsolve(x**2 - 2, x); solve(Eq(3*2**x, 7), x); solve([a*b**3 - 3, a*b**5 - 7], [a, b], dict=True)\nsolveset(sin(x) - Rational(1, 2), x, domain=S.Reals).intersect(Interval(0, 7))\nsimplify((x**2 - 1)/(x - 1)); factor(x**2 - 1); expand((x + 1)**3)\ndiff(x*exp(-x), x); integrate(x*exp(-x), x); integrate(x**2, (x, 0, 3))\nlambdify(x, exp(-x) + x**2, 'math')(1.5); nsimplify(0.25, rational=True); N(pi, 15)\n''', ns)\n    tex(sympify('sqrt(2)/2 + 3*x**2'))\n\n\n_ns = None\n\n\ndef begin():\n    global _ns\n    _ns = dict(_BASE)\n\n\ndef step(st_json):\n    st = json.loads(st_json)\n    r = {'id': st['id']}\n    buf = io.StringIO()\n    try:\n        target = dict(_ns) if st['kind'] == 'python' else _ns\n        with contextlib.redirect_stdout(buf):\n            exec(compile(st['code'], '<blok>', 'exec'), target)\n        r.update(fmt(st, target))\n    except Exception as e:\n        r['error'] = dansk_fejl(e)\n    p = buf.getvalue()\n    if p:\n        r['stdout'] = p[-6000:] if len(p) <= 6000 else '… (kun de sidste 6000 tegn vises)\\n' + p[-6000:]\n    return json.dumps(r)\n";
const MANIFEST = {"stdlib":["stdlib-1.json"],"pkgs":["pkgs-1.json","pkgs-2.json"]};
let py = null;

// --- lille zip-skriver (ukomprimeret) til Pythons standardbibliotek ---
const CRC = (() => { const t = new Uint32Array(256); for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })();
function crc32(b) { let c = 0xFFFFFFFF; for (let i = 0; i < b.length; i++) c = CRC[(c ^ b[i]) & 0xFF] ^ (c >>> 8); return (c ^ 0xFFFFFFFF) >>> 0; }
function makeZip(files) {
  const enc = new TextEncoder();
  const parts = [], central = [];
  let off = 0;
  for (const [name, text] of files) {
    const nb = enc.encode(name), data = enc.encode(text), crc = crc32(data);
    const lh = new DataView(new ArrayBuffer(30));
    lh.setUint32(0, 0x04034b50, true); lh.setUint16(4, 20, true); lh.setUint16(12, 33, true);
    lh.setUint32(14, crc, true); lh.setUint32(18, data.length, true); lh.setUint32(22, data.length, true); lh.setUint16(26, nb.length, true);
    parts.push(new Uint8Array(lh.buffer), nb, data);
    const ch = new DataView(new ArrayBuffer(46));
    ch.setUint32(0, 0x02014b50, true); ch.setUint16(4, 20, true); ch.setUint16(6, 20, true); ch.setUint16(14, 33, true);
    ch.setUint32(16, crc, true); ch.setUint32(20, data.length, true); ch.setUint32(24, data.length, true); ch.setUint16(28, nb.length, true); ch.setUint32(42, off, true);
    central.push(new Uint8Array(ch.buffer), nb);
    off += 30 + nb.length + data.length;
  }
  const cdSize = central.reduce((s, p) => s + p.length, 0);
  const end = new DataView(new ArrayBuffer(22));
  end.setUint32(0, 0x06054b50, true); end.setUint16(8, files.length, true); end.setUint16(10, files.length, true); end.setUint32(12, cdSize, true); end.setUint32(16, off, true);
  return new Blob([...parts, ...central, new Uint8Array(end.buffer)]).arrayBuffer();
}
async function getJSON(name) {
  const r = await fetch(BASE + 'py/' + name);
  if (!r.ok) throw new Error(name + ' kunne ikke hentes (' + r.status + ')');
  return r.json();
}

async function boot() {
  try {
    postMessage({ type: 'status', msg: 'Henter Python …' });
    const stdFiles = [];
    for (const n of MANIFEST.stdlib) stdFiles.push(...Object.entries(await getJSON(n)));
    const stdZip = await makeZip(stdFiles);
    const realFetch = self.fetch.bind(self);
    self.fetch = (url, opts) => String(url).endsWith('python_stdlib.zip')
      ? Promise.resolve(new Response(stdZip.slice(0), { headers: { 'Content-Type': 'application/zip' } }))
      : realFetch(url, opts);
    importScripts(BASE + 'pyodide/pyodide.js');
    py = await loadPyodide({ indexURL: BASE + 'pyodide/', stdout: () => {}, stderr: () => {} });
    postMessage({ type: 'status', msg: 'Installerer SymPy …' });
    const site = py.runPython('import site; site.getsitepackages()[0]');
    for (const n of MANIFEST.pkgs) {
      for (const [path, text] of Object.entries(await getJSON(n))) {
        const full = site + '/' + path;
        py.FS.mkdirTree(full.slice(0, full.lastIndexOf('/')));
        py.FS.writeFile(full, text);
      }
    }
    postMessage({ type: 'status', msg: 'Starter SymPy …' });
    py.FS.writeFile('/home/pyodide/cas_core.py', PY_SRC);
    py.runPython('import sys\nsys.path.insert(0, "/home/pyodide")\nimport importlib; importlib.invalidate_caches()\nimport cas_core, sympy');
    // Varm SymPy op, så den første rigtige beregning ikke går i stå (løs, differentiér, integrér, plot)
    postMessage({ type: 'status', msg: 'Gør CAS klar …' });
    try { py.runPython('cas_core.varm()'); } catch (e) {}
    const ver = py.runPython('sympy.__version__');
    postMessage({ type: 'ready', sympy: ver });
  } catch (e) {
    postMessage({ type: 'fatal', msg: String(e && e.message || e).slice(0, 300) });
  }
}
const ready = boot();

self.onmessage = async (ev) => {
  const m = ev.data;
  await ready;
  if (!py) return;
  if (m.type === 'run') {
    const core = py.pyimport('cas_core');
    core.begin();
    for (const st of m.steps) {
      let out;
      try { out = core.step(st); }
      catch (e) { out = JSON.stringify({ id: JSON.parse(st).id, error: String(e.message || e).split('\n').slice(-2).join(' ') }); }
      postMessage({ type: 'step', seq: m.seq, out });
    }
    core.destroy && core.destroy();
    postMessage({ type: 'done', seq: m.seq });
  }
};
